Commands.Command:
$dumpFile = Join-Path $env:SystemRoot 'MEMORY.DMP'
$miniDumpFolder = Join-Path $env:SystemRoot 'Minidump'
if (Test-Path -LiteralPath $dumpFile) { Remove-Item -LiteralPath $dumpFile -Force -ErrorAction Continue }
if (Test-Path -LiteralPath $miniDumpFolder) { Get-ChildItem -LiteralPath $miniDumpFolder -File -Force -ErrorAction Stop | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Continue } }

if (Test-Path -LiteralPath 'C:\Windows.old') {
    takeown /F 'C:\Windows.old' /R /A /D Y
    if ($LASTEXITCODE -ne 0) { throw 'Taking ownership of Windows.old failed.' }
    icacls 'C:\Windows.old' /grant 'Administrators:F' /T /C
    if ($LASTEXITCODE -ne 0) { throw 'Changing permissions on Windows.old failed.' }
    Remove-Item -LiteralPath 'C:\Windows.old' -Recurse -Force -ErrorAction Stop
}

$keepProfileFolder = 'REPLACE_WITH_PROFILE_FOLDER'
if ($keepProfileFolder -eq 'REPLACE_WITH_PROFILE_FOLDER' -or [string]::IsNullOrWhiteSpace($keepProfileFolder)) { throw 'Set keepProfileFolder to the primary user profile folder name first.' }
$profiles = @(Get-CimInstance Win32_UserProfile -ErrorAction Stop)
if (-not @($profiles | Where-Object { (Split-Path $_.LocalPath -Leaf) -eq $keepProfileFolder }).Count) { throw 'The profile folder to retain was not found. Enter its folder name, not a full path or UPN.' }
$profiles | Where-Object { -not $_.Special -and -not $_.Loaded -and (Split-Path $_.LocalPath -Leaf) -notin @($keepProfileFolder,'Public','Default') } | Select-Object LocalPath,SID

$keepProfileFolder = 'REPLACE_WITH_PROFILE_FOLDER'
if ($keepProfileFolder -eq 'REPLACE_WITH_PROFILE_FOLDER' -or [string]::IsNullOrWhiteSpace($keepProfileFolder)) { throw 'Set keepProfileFolder to the primary user profile folder name first and review the profile preview.' }
$profiles = @(Get-CimInstance Win32_UserProfile -ErrorAction Stop)
if (-not @($profiles | Where-Object { (Split-Path $_.LocalPath -Leaf) -eq $keepProfileFolder }).Count) { throw 'The profile folder to retain was not found. Enter its folder name, not a full path or UPN.' }
$profiles | Where-Object { -not $_.Special -and -not $_.Loaded -and (Split-Path $_.LocalPath -Leaf) -notin @($keepProfileFolder,'Public','Default') } | Remove-CimInstance -ErrorAction Continue

Get-ChildItem -LiteralPath 'C:\Users' -Directory -ErrorAction Stop | ForEach-Object {
    $tempFolder = Join-Path $_.FullName 'AppData\Local\Temp'
    if (Test-Path -LiteralPath $tempFolder) { Get-ChildItem -LiteralPath $tempFolder -Force -ErrorAction Continue | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Continue } }
}

$services = @(Get-Service -Name wuauserv,bits -ErrorAction Stop)
$runningServices = @($services | Where-Object Status -eq 'Running' | Select-Object -ExpandProperty Name)
try {
    $services | Stop-Service -Force -ErrorAction Stop
    $downloadFolder = Join-Path $env:windir 'SoftwareDistribution\Download'
    Get-ChildItem -LiteralPath $downloadFolder -Force -ErrorAction Stop | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Continue }
}
finally {
    foreach ($serviceName in $runningServices) { Start-Service -Name $serviceName -ErrorAction Continue }
}

if (Test-Path -LiteralPath 'C:\$WINDOWS.~BT') {
    takeown /F 'C:\$WINDOWS.~BT' /R /A /D Y
    if ($LASTEXITCODE -ne 0) { throw 'Taking ownership of upgrade staging files failed.' }
    icacls 'C:\$WINDOWS.~BT' /grant 'Administrators:F' /T /C
    if ($LASTEXITCODE -ne 0) { throw 'Changing permissions on upgrade staging files failed.' }
    Remove-Item -LiteralPath 'C:\$WINDOWS.~BT' -Recurse -Force -ErrorAction Stop
}

@(
if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { 'CBS Reboot Pending' }
if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { 'Windows Update Reboot Required' }
if ((Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue).PendingFileRenameOperations) { 'Pending File Rename Operations' }
) -join '; '

[PSCustomObject]@{
    CBSRebootPending = Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'
    WURebootRequired = Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'
    PendingFileRenames = $null -ne (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue).PendingFileRenameOperations
} | Format-List *
